const skillMap = new Map();

for (const item of $input.all()) {
  const data = item.json;

  if (!data.skill) continue;

  const skill = data.skill.toString().trim();
  const skillNormalized = skill.toLowerCase();

  if (!skillMap.has(skillNormalized)) {
    skillMap.set(skillNormalized, {
      skill: skill,
      skill_normalized: skillNormalized,
      total_employees: 0,
      active_employees: 0,
      aging_employees: 0,
      stale_employees: 0
    });
  }

  const record = skillMap.get(skillNormalized);

  // One employee-skill row = one employee having this skill
  record.total_employees += 1;

  // Use the activity status already calculated in Google Sheets
  const status = data.activity_status
    ? data.activity_status.toString().trim().toLowerCase()
    : "";

  if (status === "active") {
    record.active_employees += 1;
  } else if (status === "aging") {
    record.aging_employees += 1;
  } else if (status === "stale") {
    record.stale_employees += 1;
  }
}

return Array.from(skillMap.values());

const jobs = $json.data || [];

return jobs.map(job => ({
  json: job
}));

const output = [];

for (const item of $input.all()) {
  const job = item.json;

  const skills = job.technology_slugs || [];

  for (const skill of skills) {
    output.push({
      json: {
        job_id: job.id,
        job_title: job.job_title,
        company: job.company,
        location: job.location,
        skill: skill
      }
    });
  }
}

return output;

const skillMap = new Map();

for (const item of $input.all()) {
  const skill = item.json.skill;

  if (!skill) continue;

  const normalizedSkill = skill
    .toString()
    .trim()
    .toLowerCase();

  if (!skillMap.has(normalizedSkill)) {
    skillMap.set(normalizedSkill, {
      skill: normalizedSkill,
      job_count: 0,
      jobs: new Set()
    });
  }

  const record = skillMap.get(normalizedSkill);

  record.jobs.add(item.json.job_id);
  record.job_count = record.jobs.size;
}

const results = Array.from(skillMap.values())
  .map(record => ({
    json: {
      skill: record.skill,
      job_count: record.job_count
    }
  }))
  .sort((a, b) => b.json.job_count - a.json.job_count);

return results.map(item => ({
  json: {
    ...item.json,
    skill_normalized: item.json.skill
      .toString()
      .trim()
      .toLowerCase()
  }
}));

// ==========================================
// SKILL GAP ANALYSIS
// ==========================================

const marketSkills = new Map();
const internalSkills = new Map();

// ------------------------------------------
// 1. Separate Market and Internal Data
// ------------------------------------------

for (const item of $input.all()) {

  const data = item.json;

  if (!data.skill_normalized) continue;

  const skill = data.skill_normalized
    .toString()
    .trim()
    .toLowerCase();

  // ----------------------------------------
  // MARKET DATA
  // ----------------------------------------

  if (
    data.job_count !== undefined &&
    data.job_count !== null
  ) {

    marketSkills.set(skill, {
      skill: data.skill || skill,
      skill_normalized: skill,
      job_count: Number(data.job_count) || 0
    });
  }

  // ----------------------------------------
  // INTERNAL EMPLOYEE DATA
  // ----------------------------------------

  if (
    data.total_employees !== undefined &&
    data.total_employees !== null
  ) {

    // Store internal data exactly as received
    internalSkills.set(skill, {
      total_employees: Number(data.total_employees) || 0,
      active_employees: Number(data.active_employees) || 0,
      aging_employees: Number(data.aging_employees) || 0,
      stale_employees: Number(data.stale_employees) || 0
    });
  }
}


// ------------------------------------------
// 2. Create Union of All Skills
// ------------------------------------------

const allSkills = new Set([
  ...marketSkills.keys(),
  ...internalSkills.keys()
]);


// ------------------------------------------
// 3. Find Maximum Market Demand
// ------------------------------------------

let maxJobs = 1;

for (const skill of allSkills) {

  const market = marketSkills.get(skill);

  if (market && market.job_count > maxJobs) {
    maxJobs = market.job_count;
  }
}


// ------------------------------------------
// 4. Calculate Skill Gap
// ------------------------------------------

const results = [];

for (const skill of allSkills) {

  const market = marketSkills.get(skill);
  const internal = internalSkills.get(skill);

  const jobCount = market
    ? market.job_count
    : 0;

  const totalEmployees = internal
    ? internal.total_employees
    : 0;

  const activeEmployees = internal
    ? internal.active_employees
    : 0;

  const agingEmployees = internal
    ? internal.aging_employees
    : 0;

  const staleEmployees = internal
    ? internal.stale_employees
    : 0;


  // ----------------------------------------
  // Market Demand %
  // ----------------------------------------

  const marketDemandPct =
    (jobCount / maxJobs) * 100;


  // ----------------------------------------
  // Internal Active Supply %
  // ----------------------------------------

  const activeSupplyPct =
    totalEmployees > 0
      ? (activeEmployees / totalEmployees) * 100
      : 0;


  // ----------------------------------------
  // Shortage %
  // ----------------------------------------

  const shortagePct =
    100 - activeSupplyPct;


  // ----------------------------------------
  // Overall Gap Score
  // ----------------------------------------

  const gapScore =
    (marketDemandPct * 0.6) +
    (shortagePct * 0.4);


  // ----------------------------------------
  // Priority
  // ----------------------------------------

  let priority;

  if (gapScore >= 70) {
    priority = "Critical";
  }
  else if (gapScore >= 50) {
    priority = "High";
  }
  else if (gapScore >= 30) {
    priority = "Medium";
  }
  else {
    priority = "Low";
  }


  // ----------------------------------------
  // Final Record
  // ----------------------------------------

  results.push({
    json: {

      skill: market
        ? market.skill
        : skill,

      skill_normalized: skill,

      job_count: jobCount,

      market_demand_pct:
        Number(marketDemandPct.toFixed(2)),

      total_employees:
        totalEmployees,

      active_employees:
        activeEmployees,

      aging_employees:
        agingEmployees,

      stale_employees:
        staleEmployees,

      active_supply_pct:
        Number(activeSupplyPct.toFixed(2)),

      shortage_pct:
        Number(shortagePct.toFixed(2)),

      gap_score:
        Number(gapScore.toFixed(2)),

      priority:
        priority
    }
  });
}


// ------------------------------------------
// 5. Highest Gap First
// ------------------------------------------

results.sort(
  (a, b) =>
    b.json.gap_score -
    a.json.gap_score
);


// ------------------------------------------
// 6. Return Results
// ------------------------------------------

return results;

// ==========================================
// PRIORITY SKILLS - BATCH FOR AI
// ==========================================

const prioritySkills = [];

for (const item of $input.all()) {

  const data = item.json;

  if (
    data.priority === "Critical" ||
    data.priority === "High"
  ) {

    prioritySkills.push({
      skill: data.skill,
      skill_normalized: data.skill_normalized,

      job_count: data.job_count,
      market_demand_pct: data.market_demand_pct,

      total_employees: data.total_employees,
      active_employees: data.active_employees,
      aging_employees: data.aging_employees,
      stale_employees: data.stale_employees,

      active_supply_pct: data.active_supply_pct,
      shortage_pct: data.shortage_pct,

      gap_score: data.gap_score,
      priority: data.priority
    });
  }
}

// Highest gap first
prioritySkills.sort(
  (a, b) => b.gap_score - a.gap_score
);

// Send ALL priority skills as ONE item
return [
  {
    json: {
      total_priority_skills: prioritySkills.length,
      priority_skills: prioritySkills
    }
  }
];

