// ==========================================
// EMPLOYEE SKILL MATCHING - IMPROVED
// Direct + Related skill candidates
// ==========================================

// 1. Get AI workforce recommendations
const aiInput = $input.first().json;

const recommendations =
  aiInput.output?.recommendations ||
  aiInput.recommendations ||
  [];


// 2. Get all employee-skill records
const employeeItems =
  $("Get row(s) in sheet").all();


// 3. Helper functions
function normalize(value) {

  if (!value) return "";

  return value
    .toString()
    .trim()
    .toLowerCase()
    .replace(/[_-]+/g, " ");
}


function parseSkills(value) {

  if (!value) return [];

  return value
    .toString()
    .split(",")
    .map(skill => normalize(skill))
    .filter(Boolean);
}


// 4. Final results
const results = [];


// 5. Process every priority skill
for (const recommendation of recommendations) {

  const targetSkill =
    normalize(recommendation.skill);

  const priority =
    recommendation.priority || "Medium";

  const workforceAction =
    recommendation.recommended_action || "Monitor";


  const directCandidates = [];
  const relatedCandidates = [];


  // ----------------------------------------
  // Find employee candidates
  // ----------------------------------------

  for (const employeeItem of employeeItems) {

    const employee = employeeItem.json;

    const employeeSkill =
      normalize(employee.skill);

    const relatedSkills =
      parseSkills(employee.related_skills);


    let matchType = "";
    let matchScore = 0;


    // DIRECT MATCH
    if (employeeSkill === targetSkill) {

      matchType = "Direct";
      matchScore = 60;
    }


    // RELATED MATCH
    else if (relatedSkills.includes(targetSkill)) {

      matchType = "Related";
      matchScore = 40;
    }


    // No match
    else {
      continue;
    }


    // --------------------------------------
    // Skill level
    // --------------------------------------

    const level =
      normalize(employee.skill_level);

    if (level === "advanced") {
      matchScore += 20;
    }
    else if (level === "intermediate") {
      matchScore += 15;
    }
    else if (level === "beginner") {
      matchScore += 8;
    }


    // --------------------------------------
    // Activity status
    // --------------------------------------

    const status =
      normalize(employee.activity_status);

    if (status === "active") {
      matchScore += 15;
    }
    else if (status === "aging") {
      matchScore += 8;
    }
    else if (status === "stale") {
      matchScore += 3;
    }


    // --------------------------------------
    // Experience
    // --------------------------------------

    const experience =
      Number(employee.years_of_experience) || 0;

    if (experience >= 5) {
      matchScore += 5;
    }
    else if (experience >= 2) {
      matchScore += 3;
    }


    // --------------------------------------
    // Employee-level action
    // --------------------------------------

    let employeeAction;


    // Existing employee already has target skill
    if (matchType === "Direct") {

      if (
        status === "aging" ||
        status === "stale"
      ) {

        employeeAction = "Refresh";

      } else {

        employeeAction = "Upskill";
      }
    }


    // Employee has related capability
    else {

      employeeAction = "Reskill";
    }


    const candidate = {

      employee_id:
        employee.employee_id,

      employee_name:
        employee.employee_name,

      department:
        employee.department,

      job_role:
        employee.job_role,

      current_skill:
        employee.skill,

      skill_level:
        employee.skill_level,

      activity_status:
        employee.activity_status,

      months_since_last_used:
        employee.months_since_last_used,

      years_of_experience:
        employee.years_of_experience,

      target_skill:
        recommendation.skill,

      priority:
        priority,

      workforce_action:
        workforceAction,

      employee_action:
        employeeAction,

      match_type:
        matchType,

      fit_score:
        Math.min(matchScore, 100)
    };


    // Separate direct and related candidates
    if (matchType === "Direct") {

      directCandidates.push(candidate);

    } else {

      relatedCandidates.push(candidate);
    }
  }


  // ----------------------------------------
  // Sort each group by fit
  // ----------------------------------------

  directCandidates.sort(
    (a, b) => b.fit_score - a.fit_score
  );

  relatedCandidates.sort(
    (a, b) => b.fit_score - a.fit_score
  );


  // ----------------------------------------
  // Keep both types
  // Maximum 5 each
  // ----------------------------------------

  const selectedCandidates = [
    ...directCandidates.slice(0, 5),
    ...relatedCandidates.slice(0, 5)
  ];


  // ----------------------------------------
  // Add to results
  // ----------------------------------------

  for (const candidate of selectedCandidates) {

    results.push({
      json: candidate
    });
  }
}


// ------------------------------------------
// Return employee recommendations
// ------------------------------------------

return results;

// ==========================================
// BATCH EMPLOYEE RECOMMENDATIONS
// ==========================================

const employees = $input.all().map(item => item.json);

// Sort strongest candidates first
employees.sort(
  (a, b) => (b.fit_score || 0) - (a.fit_score || 0)
);

// Send all employee recommendations as ONE item
return [
  {
    json: {
      total_employee_recommendations: employees.length,
      employee_recommendations: employees
    }
  }
];

// ==========================================
// FORMAT EMPLOYEE AI RECOMMENDATIONS
// Convert AI array into individual rows
// ==========================================

const data = $input.first().json;

// Get recommendations from AI output
const recommendations =
  data.output?.recommendations ||
  data.recommendations ||
  [];

// Convert each recommendation into one n8n item
return recommendations.map(rec => ({
  json: {
    employee_id: rec.employee_id,
    employee_name: rec.employee_name,

    current_skill: rec.current_skill,
    target_skill: rec.target_skill,

    priority: rec.priority,
    match_type: rec.match_type,
    fit_score: rec.fit_score,

    recommended_action: rec.recommended_action,

    development_recommendation:
      rec.development_recommendation,

    reason: rec.reason,
    urgency: rec.urgency
  }
}));
